css:
.d-table-page-size{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-page-size *,.d-table-page-size *::before,.d-table-page-size *::after{box-sizing:border-box}
.d-table-page-size [hidden]{display:none!important}
.d-table-page-size .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-page-size .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-page-size label{display:block;margin:8px 0}
.d-table-page-size input,.d-table-page-size select,.d-table-page-size textarea,.d-table-page-size button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-page-size input:not([type=checkbox]):not([type=radio]),.d-table-page-size select,.d-table-page-size textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-page-size button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-page-size button:disabled{opacity:.5;cursor:default}
.d-table-page-size :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-page-size [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-page-size .d-scroll{max-width:100%;overflow:auto}
.d-table-page-size table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-page-size th,.d-table-page-size td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-page-size caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-page-size progress{width:100%;accent-color:var(--ink)}
.d-table-page-size pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-page-size h3,.d-table-page-size p{margin:8px 0}
.d-table-page-size [aria-pressed=true],.d-table-page-size [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-page-size .d-grow{flex:1;min-width:100px}
.d-table-page-size summary{cursor:pointer;padding:6px 0}
.d-table-page-size ul,.d-table-page-size ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const records=qa('tbody tr');let page=0;const draw=()=>{const size=Number(q('[data-size]').value),pages=Math.ceil(records.length/size);page=Math.min(page,pages-1);records.forEach((row,index)=>row.hidden=index<page*size||index>=(page+1)*size);q('[data-prev]').disabled=page===0;q('[data-next]').disabled=page===pages-1;q('[data-page]').textContent=(page+1)+' / '+pages;say('共 '+records.length+' 条');};q('[data-prev]').onclick=()=>{page--;draw();};q('[data-next]').onclick=()=>{page++;draw();};q('[data-size]').onchange=()=>{page=0;draw();};draw();})(root, q, qa, say);
}
